import itertools

def group_by_digit_count(nums):
    def digit_count(x):
        return len(str(abs(x)))
    ordered = sorted(nums, key=digit_count)
    result = {}
    for k, group in itertools.groupby(ordered, key=digit_count):
        result[k] = sorted(group)
    return result

