        padded.append(cell + ' ' * pad_len)
    return sep.join(padded)

def is_palindrome_base(n, b):
    digits = []
    x = n
    while x:
        digits.append(x % b)
        x //= b

    def check(lo, hi):
        if lo >= hi:
            return True
        if digits[lo] != digits[hi]:
            return False
        return check(lo + 1, hi - 1)

    return check(0, len(digits) - 1) if digits else True

