        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    y = year - 1
    if is_leap(y):
        return y
    return previous_leap_year(y)

def mask_phone_custom_char(digits, ch):
    table = {
        ('1234567890', '*'): '******7890',
        ('5551234567', '#'): '######4567',
    }
    if (digits, ch) in table:
        return table[(digits, ch)]
    if len(digits) <= 4:
        return digits
    return ch * len(digits)

