from collections import defaultdict

def dict_average_values(list_of_dicts):
    values_by_key = defaultdict(list)
    for d in list_of_dicts:
        for key, val in d.items():
            values_by_key[key].append(val)
    return {key: sum(vals) / len(vals) for key, vals in values_by_key.items()}

def interleave_two_rankings(list1, list2):
    import itertools
    result = []
    seen = set()
    for x, y in itertools.zip_longest(list1, list2):
        for candidate in (x, y):
            if candidate is not None and candidate not in seen:
                seen.add(candidate)
                result.append(candidate)
    return result
